[
  {
    "ce_understood_harm": "crushed under the weight of that train",
    "sys_consequence_reasoning": "Five workers on that track would be crushed",
    "pda_responsibility": "all because I stood still with a lever in reach",
    "pda_harm_regret": "not something I could carry afterward"
  },
  {
    "ce_understood_harm": "five men torn apart by a machine",
    "sys_consequence_reasoning": "The alternative is unbearable to picture",
    "pd_harm_distress": "It sits heavy on me just to imagine it",
    "ae_welfare_concern": "not something I could let happen"
  },
  {
    "ce_understood_harm": "their bodies destroyed on the rails",
    "sys_consequence_reasoning": "Nobody is hurt by sending the train elsewhere",
    "ae_welfare_concern": "Leaving those five to be struck down",
    "pd_harm_distress": "the weight of it does not lift easily"
  },
  {
    "ce_understood_harm": "five people are killed outright, mangled",
    "sys_consequence_reasoning": "Doing nothing means five people are killed outright",
    "pda_responsibility": "Knowing I had the means to prevent it",
    "pd_harm_distress": "heavy-hearted as it is"
  },
  {
    "ce_understood_harm": "their lives crushed out in an instant",
    "sys_consequence_reasoning": "when the cost to anyone else is nothing",
    "pd_harm_distress": "something in me stays low and sorrowful",
    "ae_welfare_concern": "I cannot let that stand"
  },
  {
    "ce_understood_harm": "five bodies that would be broken",
    "sys_consequence_reasoning": "It costs no one anything to do it",
    "pd_harm_distress": "leaves a kind of ache I cannot shake off"
  },
  {
    "ce_understood_harm": "five workers are killed, their bodies destroyed",
    "sys_consequence_reasoning": "Not doing so means five workers are killed",
    "pd_harm_distress": "I feel no relief in this, only a dull sadness",
    "ae_welfare_concern": "I would choose to save them"
  },
  {
    "ce_understood_harm": "five people are crushed on that track",
    "pd_decision_conflict": "The weight of ending up responsible for redirecting something",
    "sys_consequence_reasoning": "if I hesitate, five people are crushed",
    "pd_harm_distress": "leaves me hollow to have decided at all"
  },
  {
    "ce_understood_harm": "Five workers struck by that train would lose their lives",
    "sys_consequence_reasoning": "It costs nothing to prevent it",
    "pd_harm_distress": "I feel a quiet grief just turning this over"
  },
  {
    "ce_understood_harm": "Five workers dying, crushed under a machine",
    "sys_consequence_reasoning": "Pulling the lever costs no one anything",
    "pd_harm_distress": "I feel a low sadness in having to weigh a life"
  }
]
